
// Major additions from the coverage review.
Object.assign(SOURCES,{"ife_met":{"publisher":"The Metropolitan Museum of Art","title":"Ife (from ca. 6th Century)","url":"https://www.metmuseum.org/pt/essays/ife-from-ca-6th-century"},"kilwa_unesco":{"publisher":"UNESCO World Heritage Centre","title":"Ruins of Kilwa Kisiwani and Songo Mnara","url":"https://whc.unesco.org/en/list/144/"},"asante_met":{"publisher":"The Metropolitan Museum of Art","title":"Guinea Coast, 1600–1800 A.D.","url":"https://www.metmuseum.org/it/toah/ht/09/afg.html"},"kongo_history":{"publisher":"South African History Online","title":"Kingdom of Kongo, 1390–1914","url":"https://sahistory.org.za/article/kingdom-kongo-1390-1914"},"mongol_rubin":{"publisher":"Rubin Museum of Himalayan Art","title":"Mongol Empire","url":"https://rubinmuseum.org/projecthimalayanart/resources/mongol-empire-ca-1206-1368/"},"ming_met":{"publisher":"The Metropolitan Museum of Art","title":"Arts of the Ming Dynasty: Yuan, Ming and Qing chronology","url":"https://www.metmuseum.org/exhibitions/listings/2009/arts-of-the-ming-dynasty"},"iran_met":{"publisher":"The Metropolitan Museum of Art","title":"Iran, 500–1000 A.D.","url":"https://www.metmuseum.org/de/toah/ht/06/wai.html"},"andes_met":{"publisher":"The Metropolitan Museum of Art","title":"Central and Southern Andes, 1–500 A.D.","url":"https://www.metmuseum.org/pt/toah/ht/05/sac.html"},"chaco_unesco":{"publisher":"UNESCO World Heritage Centre","title":"Chaco Culture","url":"https://whc.unesco.org/en/list/353/"},"vijayanagara_art":{"publisher":"Smarthistory · published art-historical scholarship","title":"Art and architecture of the Vijayanagara empire","url":"https://smarthistory.org/art-and-architecture-of-vijayanagara-empire/"},"chola_art":{"publisher":"Smarthistory · published art-historical scholarship","title":"Chola Empire, 850–1279","url":"https://smarthistory.org/period-culture-style/chola-empire/"}});
const COVERAGE_REFERENCES={"ife":["ife_met"],"kilwa":["kilwa_unesco"],"asante":["asante_met"],"kongo":["kongo_history"],"mongol":["mongol_rubin"],"ming":["ming_met"],"yuan":["ming_met"],"qing":["ming_met"],"sasanian":["iran_met"],"umayyad":["iran_met"],"moche":["andes_met"],"wari":["andes_met"],"chaco":["chaco_unesco"],"vijayanagara":["vijayanagara_art"],"chola":["chola_art"]};
const COVERAGE_ADDITIONS=[["ife","Ife · artistic flourishing","africa",1200,1500,"Urban phase","Approximate","Southwestern Nigeria","Ife became a major Yoruba centre of naturalistic terracotta and metal sculpture.","The city’s origins reach back to at least the sixth century. This bar selects its major medieval artistic phase; Ife remains a living city.","Ife"],["oyo","Oyo · imperial expansion","africa",1600,1836,"Political power","Approximate","Yoruba region · present-day Nigeria and Benin","Oyo developed a powerful cavalry-based empire and extensive regional political and commercial connections.","This shows the principal imperial phase, not the disputed date of Oyo’s founding. The Alaafin’s institution and Yoruba societies continued after imperial collapse.","Oyo Empire"],["asante","Asante Empire","africa",1701,1902,"Political power","Conventional","West Africa · present-day Ghana","An Akan state developed influential political institutions, trade networks and court arts.","1701 marks consolidation after the defeat of Denkyira. British annexation was proclaimed in 1901 and took effect in 1902; the Asante monarchy and culture continued.","Ashanti Empire"],["kongo","Kingdom of Kongo","africa",1390,1914,"Political power","Approximate","West-central Africa · present-day Angola and the two Congos","A major Central African kingdom developed regional networks and a long, changing relationship with Portugal.","The foundation date is approximate. Sovereignty weakened before formal suppression of the kingship in 1914; Kongo peoples and traditions continued.","Kingdom of Kongo"],["kilwa","Kilwa · Swahili trading city","africa",800,1900,"Urban centre","Approximate","Indian Ocean coast · present-day Tanzania","Kilwa linked the East African coast with commerce across the Indian Ocean.","UNESCO places occupation between the ninth and nineteenth centuries, with prosperity peaking in the thirteenth and fourteenth. These are century anchors, not exact founding and ending dates.","Kilwa Kisiwani"],["ethiopia","Solomonic Ethiopia","africa",1270,1974,"Political power","Conventional","Horn of Africa · present-day Ethiopia and Eritrea","Solomonic rulers presided over a long history of changing imperial authority in the Ethiopian highlands.","A dynastic frame including interruptions and periods of fragmented authority. The bar does not imply that Ethiopian statehood or culture began in 1270.","Solomonic dynasty"],["kanem","Kanem Empire","africa",700,1380,"Political power","Approximate","Lake Chad basin · mainly present-day Chad","A Sahelian state connected communities around Lake Chad with trans-Saharan networks.","Early chronology is uncertain. The late-fourteenth-century endpoint marks a shift of the ruling dynasty towards Bornu, rather than the disappearance of the region’s societies.","Kanem Empire"],["bornu","Bornu Empire","africa",1380,1893,"Political power","Approximate","Lake Chad basin · mainly present-day Nigeria","Bornu became a major centre of power west of Lake Chad under rulers linked to the earlier Kanem state.","The foundation date is rounded. The fall of the capital to Rabih in 1893 marks an important political rupture; later Borno institutions continued.","Bornu Empire"],["hittite","Hittite kingdom and empire","westasia",-1650,-1180,"Political power","Approximate","Anatolia · present-day Türkiye","Hittite rulers developed a major Anatolian state and participated in the diplomacy of the Late Bronze Age.","The bar groups changing phases of Hittite rule. Later Neo-Hittite states and communities continued after the imperial collapse.","Hittites"],["phoenicia","Phoenician city-states","westasia",-1200,-332,"Regional period","Approximate","Eastern Mediterranean · mainly present-day Lebanon","Maritime city-states including Tyre, Sidon and Byblos maintained extensive Mediterranean connections.","This is a selected period of city-state history, not one Phoenician empire. Alexander’s conquest of Tyre is not an end date for Phoenician or Punic peoples.","Phoenicia"],["sasanian","Sasanian Empire","westasia",224,651,"Political power","Conventional","Iranian plateau and Mesopotamia","An Iranian empire competed and exchanged ideas with Rome and other neighbouring powers.","The dynasty’s political ending does not mark the end of Iranian society, religion or administrative traditions.","Sasanian Empire"],["rashidun","Rashidun caliphate","westasia",632,661,"Political power","Conventional","Arabia and expanding neighbouring territories","The first caliphs led a rapidly expanding state after the death of Muhammad.","This is a political period in early Islamic history. It is not the beginning or end of Islam as a religious tradition.","Rashidun Caliphate"],["umayyad","Umayyad caliphate · Damascus","westasia",661,750,"Political power","Conventional","West Asia, North Africa and Iberia","A dynasty based in Damascus governed a realm extending across several world regions.","The Damascus caliphate ended in 750, while an Umayyad dynasty continued in Iberia. Placement identifies a centre of rule, not its territorial extent.","Umayyad Caliphate"],["seljuq","Great Seljuq Empire","westasia",1037,1194,"Political power","Conventional","Central and West Asia","A Turkic-led empire shaped political and cultural life across much of the Iranian world.","The dates concern the Great Seljuq polity; Seljuq successor states, including the Sultanate of Rum, had different lifespans.","Seljuk Empire"],["safavid","Safavid Iran","westasia",1501,1736,"Political power","Conventional","Iranian plateau and neighbouring regions","Safavid rulers established a major Iranian state and sponsored influential court arts.","The dynasty lost effective control of its capital in 1722. The 1736 endpoint refers to formal replacement; it does not imply uniform control throughout.","Safavid Iran"],["kushan","Kushan Empire","southasia",30,375,"Political power","Approximate","Central and South Asia · Afghanistan, Pakistan and northern India","Kushan rulers connected major trading and cultural networks, including centres of Buddhist patronage.","A broad museum-style period range. The chronology and limits of effective rule vary, and later Kushan-related polities are not all represented.","Kushan Empire"],["chola","Medieval Chola dynasty","southasia",850,1279,"Political power","Approximate","Southern India, Sri Lanka and the Bay of Bengal","Chola rulers sponsored major temples, sculpture and maritime connections across the Bay of Bengal.","This selects the medieval imperial phase. Chola names and lineages occur earlier; the dates do not describe all Tamil history.","Chola dynasty"],["delhi","Delhi Sultanate","southasia",1206,1526,"Political power","Conventional","Northern Indian subcontinent and changing adjoining territories","Successive ruling dynasties based in Delhi governed changing parts of South Asia.","Five major dynasties are grouped here. The extent of their rule varied; southern states and other independent powers coexisted.","Delhi Sultanate"],["vijayanagara","Vijayanagara Empire","southasia",1336,1646,"Political power","Conventional","Southern India · capital at present-day Hampi","A major southern Indian empire developed a monumental capital and extensive regional networks.","The defeat of 1565 transformed the empire, but successor rulers continued beyond the destruction of the main capital.","Vijayanagara Empire"],["maratha","Maratha polity","southasia",1674,1818,"Political power","Conventional","Indian subcontinent · centred in the western Deccan","Maratha rulers and confederated houses became major powers in the subcontinent.","The frame runs from Shivaji’s coronation to the defeat of the Peshwa. Several Maratha-ruled princely states continued after 1818.","Maratha Empire"],["qin","Qin dynasty","eastasia",-221,-206,"Political power","Conventional","East Asia · present-day China","A short-lived dynasty unified competing states under an imperial ruler.","The Qin state existed before 221 BCE. This short bar represents the imperial dynasty; it remains selectable even when its label needs magnification.","Qin dynasty"],["sui","Sui dynasty","eastasia",581,618,"Political power","Conventional","East Asia · present-day China","The Sui reunited northern and southern realms before the Tang dynasty.","Dynastic dates should not be confused with uniform control across all regions for the entire period.","Sui dynasty"],["mongol","Mongol Empire · unified phase","eastasia",1206,1260,"Political power","Conventional","Founded in Mongolia · expansion across Eurasia","Mongol armies and rulers connected an exceptionally extensive Eurasian imperial realm.","1260 marks a conventional transition into competing khanates. Mongol states continued much longer, including the Yuan dynasty shown separately.","Mongol Empire"],["yuan","Yuan dynasty","eastasia",1271,1368,"Political power","Conventional","East Asia · centred in present-day China","Kublai Khan proclaimed the Yuan dynasty during the wider history of Mongol rule.","1271 is the dynastic proclamation; conquest of the Southern Song was completed in 1279. Northern Yuan rulers continued after losing China in 1368.","Yuan dynasty"],["ming","Ming dynasty","eastasia",1368,1644,"Political power","Conventional","East Asia · present-day China","Ming rulers governed a major imperial state with extensive regional and maritime connections.","1644 marks the fall of Beijing and the main dynasty. Southern Ming regimes continued after that date.","Ming dynasty"],["qing","Qing dynasty","eastasia",1644,1912,"Political power","Conventional","East and Inner Asia","A Manchu-led dynasty governed an expansive and diverse empire.","1644 marks entry into Beijing rather than the dynasty’s 1636 proclamation. Some art chronologies end in 1911; the emperor abdicated in 1912.","Qing dynasty"],["heian","Heian period","eastasia",794,1185,"Regional period","Conventional","Japanese archipelago","Court culture developed around Heian-kyō while political institutions changed over time.","This is a historical period, not the full lifespan of a single Japanese state. Alternative endpoints include 1192.","Heian period"],["goryeo","Goryeo dynasty","eastasia",918,1392,"Political power","Conventional","Korean peninsula","A Korean dynasty supported influential Buddhist, ceramic and printing traditions.","918 marks the dynasty’s foundation; unification of the later Three Kingdoms was completed in 936.","Goryeo"],["srivijaya","Srivijaya","eastasia",650,1377,"Political power","Debated","Maritime Southeast Asia · centred on Sumatra","A maritime polity linked ports, Buddhist institutions and commercial networks across Southeast Asia.","Origins, centres of power and the end of the polity are debated. This broad range should not imply continuous control of all regional shipping.","Srivijaya"],["majapahit","Majapahit","eastasia",1293,1527,"Political power","Debated","Maritime Southeast Asia · centred on Java","A Javanese court cultivated political and commercial relationships across the archipelago.","Claims of influence should not be treated as a map of uniformly administered territory. The decline and final endpoint remain debated.","Majapahit"],["mycenaean","Mycenaean societies","europe",-1600,-1100,"Archaeological culture","Approximate","Greek mainland and Aegean","Palatial centres and Linear B records illuminate the Late Bronze Age Greek world.","This is an archaeological period grouping several centres. The collapse of palace systems did not end Greek-speaking communities.","Mycenaean Greece"],["romanrepublic","Roman Republic","europe",-509,-27,"Political power","Conventional","Mediterranean · centred on Rome","Republican institutions accompanied Rome’s expansion into a major Mediterranean power.","509 BCE is a traditional date for the republic’s foundation; 27 BCE is the conventional beginning of the principate, not an instant change in every institution.","Roman Republic"],["hellenistic","Hellenistic kingdoms","europe",-323,-31,"Regional period","Conventional","Mediterranean and West Asia","Successor kingdoms emerged after Alexander’s death and fostered interconnected cultural worlds.","This groups independent and competing kingdoms across several regions. The 31 BCE endpoint follows a common period convention.","Hellenistic period"],["holyroman","Holy Roman Empire","europe",962,1806,"Political power","Conventional","Central Europe and changing neighbouring territories","An imperial framework connected many kingdoms, principalities and cities in Central Europe.","Some histories begin with Charlemagne in 800. This bar uses Otto I’s coronation in 962; the empire was not a modern centralised nation-state.","Holy Roman Empire"],["rus","Kyivan Rusʹ","europe",882,1240,"Political power","Conventional","Eastern Europe · centred on Kyiv and other cities","A network of principalities developed political, commercial and religious connections across Eastern Europe.","The conventional frame simplifies regional fragmentation and the Mongol invasions. It does not assign the medieval polity exclusively to one modern nation.","Kievan Rus'"],["moche","Moche traditions","americas",100,800,"Archaeological culture","Approximate","Northern coastal Andes · present-day Peru","Regional communities produced monumental adobe centres and distinctive ceramic and metal arts.","Moche is an archaeological designation encompassing changing regional centres, not proof of one uninterrupted empire.","Moche culture"],["nazca","Nazca traditions","americas",-100,800,"Archaeological culture","Approximate","Southern coastal Andes · present-day Peru","Communities developed distinctive ceramics, textiles and monumental geoglyphs.","Period boundaries vary. The geoglyphs include work from different communities and phases, and do not define the entire history of the region.","Nazca culture"],["chaco","Chaco Canyon","americas",850,1250,"Urban phase","Approximate","Southwestern North America · present-day United States","Ancestral Pueblo communities built major ceremonial and residential centres connected across the region.","This selects the major Chacoan phase. Pueblo peoples and their cultural traditions continue; the endpoint does not mean their disappearance.","Chaco Culture National Historical Park"],["wari","Wari · expansion","americas",600,1000,"Archaeological culture","Approximate","Central Andes · present-day Peru","Urban centres and regional networks expanded around the Wari state and its material traditions.","This selects the main expansion phase. Some archaeological periodisations begin Wari material traditions earlier; the degree of state control varied across regions.","Wari culture"],["tiwanaku","Tiwanaku","americas",500,1000,"Urban phase","Approximate","Lake Titicaca basin · present-day Bolivia and neighbouring areas","A major highland centre influenced religious and regional networks around Lake Titicaca.","This selects a period of expansion and florescence. Settlement at the site began earlier, and regional communities continued afterward.","Tiwanaku"],["tonga","Tuʻi Tonga","oceania",950,1865,"Political power","Debated","Tonga and wider western Polynesian networks","Tongan chiefly authority developed extensive political and cultural relationships across the Pacific.","The early chronology draws heavily on genealogies. The bar groups changing chiefly arrangements rather than asserting direct administration of a single Pacific empire.","Tuʻi Tonga Empire"],["rapanui","Rapa Nui · monumental phase","oceania",1200,1600,"Urban phase","Approximate","Rapa Nui / Easter Island · southeastern Pacific","Rapa Nui communities constructed monumental platforms and moai within a distinctive island society.","A selected broad monumental phase. Initial settlement and monument chronologies remain subjects of research; Rapa Nui people and culture continue.","Moai"]];
for(const [id,title,region,start,end,type,status,location,summary,note] of COVERAGE_ADDITIONS){const format=y=>Math.abs(y)+' '+(y<0?'BCE':'CE');HISTORIES.push({id,title,region,start,end,dates:(status==='Approximate'||status==='Debated'?'c. ':'')+format(start)+'–'+format(end),type,status,location,summary,note,sources:[...(COVERAGE_REFERENCES[id]||[]),'wikipedia_'+id]});}
